package dev.zomboid.mts;
import java.util.*;import minecrafttransportsimulator.entities.instances.*;import minecrafttransportsimulator.mcinterface.InterfaceManager;
public class Checks {
 static int count;static void check(boolean b,String msg){count++;if(!b)throw new AssertionError(msg);}
 public static class Variable {public double currentValue;public boolean isActive;public Variable(double n){currentValue=n;isActive=n!=0;}public void setActive(boolean b,boolean sync){currentValue=b?1:0;isActive=b;}}
 public static class General {public double health=150;}public static class Motorized {public double fuelCapacity=1000;}
 public static class Definition {public String packID="mtsofficialpack",systemName="scout";public General general=new General();public Motorized motorized=new Motorized();public List<Slot> parts=new ArrayList<>();public List<Object> instruments=new ArrayList<>();}
 public static class Slot {public String defaultPart="mtsofficialpack:zomboid_trunk";}public static class World {public boolean client;public boolean isClient(){return client;}}
 public static class Callback {public boolean canceled;public void cancel(){canceled=true;}}
 public static class Event {boolean attack,use,canceled,swing=true;String hand="MAIN_HAND";public Event(boolean a,boolean u){attack=a;use=u;}public boolean isAttack(){return attack;}public boolean isUseItem(){return use;}public String getHand(){return hand;}public void setCanceled(boolean c){canceled=c;}public void setSwingHand(boolean s){swing=s;}}
 public static class Held {boolean empty=true;public boolean isEmpty(){return empty;}}public static class Player {public Object seat;public Held held=new Held();public Object getEntityRiding(){return seat;}public Held getHeldStack(){return held;}}
 public static class Placement {public boolean isController=true;}public static class Tank {public double getFluidLevel(){return 500;}}
 public static class GUI {public Object vehicle;GUI(Object v){vehicle=v;}}
 public static void main(String[] args){
 check(Mechanics.fraction(0,100)==1,"full health");check(Mechanics.fraction(50,100)==.5,"half");check(Mechanics.fraction(250,100)==0,"cannot negative");check(Mechanics.fraction(-10,100)==1,"cannot exceed max");
 EntityVehicleF_Physics car=new EntityVehicleF_Physics();PartEngine engine=new PartEngine();engine.vehicleOn=car;car.engines.add(engine);PartSeat seat=new PartSeat();seat.vehicleOn=car;Player player=new Player();player.seat=seat;InterfaceManager.clientInterface.player=player;
 check(Mechanics.car(car),"official road vehicle");car.definition.systemName="bell206";check(!Mechanics.car(car),"aircraft unchanged");car.definition.systemName="scout";
 Event left=new Event(true,false);Mechanics.click(left);check(left.canceled&&!left.swing,"manual consumes click and swing");check(InterfaceManager.packetInterface.packets.size()==1,"single gear packet");var packet=(minecrafttransportsimulator.packets.instances.PacketEntityVariableSet)InterfaceManager.packetInterface.packets.get(0);check(packet.var==engine.shiftUpVar&&packet.value==1,"left shifts up");
 Event right=new Event(false,true);Mechanics.click(right);packet=(minecrafttransportsimulator.packets.instances.PacketEntityVariableSet)InterfaceManager.packetInterface.packets.get(1);check(packet.var==engine.shiftDownVar,"right shifts down");
 right=new Event(false,true);right.hand="OFF_HAND";Mechanics.click(right);check(right.canceled&&InterfaceManager.packetInterface.packets.size()==2,"offhand does not double shift");
 player.held.empty=false;Mechanics.click(new Event(true,false));check(InterfaceManager.packetInterface.packets.size()==2&&Mechanics.noticeUntil>System.currentTimeMillis(),"held object prevents gear and warns");player.held.empty=true;
 engine.isAutomaticVar.setActive(true,false);Event auto=new Event(true,false);Mechanics.click(auto);check(!auto.canceled&&InterfaceManager.packetInterface.packets.size()==2,"automatic leaves clicks alone");
 engine.getOrCreateVariable("pz_manual_gearbox").currentValue=1;Mechanics.gearDefaults(engine);check(!engine.isAutomaticVar.isActive,"manual overrides native defaults");engine.getOrCreateVariable("pz_manual_gearbox").currentValue=2;Mechanics.gearDefaults(engine);check(engine.isAutomaticVar.isActive,"automatic mode restored");
 Mechanics.toggle(new GUI(car));packet=(minecrafttransportsimulator.packets.instances.PacketEntityVariableSet)InterfaceManager.packetInterface.packets.get(2);check(packet.value==1,"toggle chooses manual from automatic");
 car.lockedVar.setActive(true,false);Mechanics.toggle(new GUI(car));check(InterfaceManager.packetInterface.packets.size()==3,"cannot toggle locked car");car.lockedVar.setActive(false,false);
 seat.placementDefinition.isController=false;engine.isAutomaticVar.setActive(false,false);Event passenger=new Event(true,false);Mechanics.click(passenger);check(!passenger.canceled&&InterfaceManager.packetInterface.packets.size()==3,"passenger cannot shift");
 seat.placementDefinition.isController=true;player.seat=null;Mechanics.click(new Event(true,false));check(InterfaceManager.packetInterface.packets.size()==3,"no vehicle no shift");
 engine.damageVar.currentValue=20;engine.hoursVar.currentValue=12;List<String> lines=Mechanics.report(car);check(lines.stream().anyMatch(l->l.contains("mantenimiento")),"diagnostic detects wear");check(lines.stream().anyMatch(l->l.contains("manual")),"diagnostic indicates mode");
 check(Mechanics.severity(.8)==0&&Mechanics.severity(.5)==20&&Mechanics.severity(.1)==40,"condition colors");
  car.definition.parts.add(new Slot());Object savedCargo=new Object();car.partsInSlots.put(0,savedCargo);car.definition.parts.add(new Slot());Mechanics.ensure(car);check(car.added==1&&car.partsInSlots.get(0)==savedCargo&&car.partsInSlots.containsKey(1),"adds missing rear trunk without replacing old cargo");Mechanics.ensure(car);check(car.added==1,"no second trunk on repeated load");car.partsInSlots.remove(1);car.world.client=true;Mechanics.ensure(car);check(car.added==1,"client cannot create inventory");
  player.seat=seat;engine.isAutomaticVar.setActive(false,false);Callback cb=new Callback();int before=InterfaceManager.packetInterface.packets.size();Mechanics.raw(42,0,1,cb);check(cb.canceled&&InterfaceManager.packetInterface.packets.size()==before+1,"raw manual click precedes isometric interactions");cb=new Callback();Mechanics.raw(42,0,0,cb);check(cb.canceled&&InterfaceManager.packetInterface.packets.size()==before+1,"release does not shift twice");Mechanics.raw(42,0,2,new Callback());check(InterfaceManager.packetInterface.packets.size()==before+1,"repeat ignored");net.minecraft.client.Minecraft.getInstance().screen=new Object();Mechanics.raw(42,0,1,new Callback());check(InterfaceManager.packetInterface.packets.size()==before+1,"menu clicks don't change gears");net.minecraft.client.Minecraft.getInstance().screen=null;Mechanics.raw(99,0,1,new Callback());check(InterfaceManager.packetInterface.packets.size()==before+1,"other window ignored");
  System.out.println("Simulated mechanic checks passed: "+count);
 }
}
